#!/usr/bin/env python3
"""Resumable, parallel execution of the frozen reviewed EventPilot release."""
from __future__ import annotations
import argparse
import asyncio
import copy
import json
import os
import random
import sys
import time
import tempfile
from importlib.metadata import version, PackageNotFoundError
from contextlib import contextmanager
from pathlib import Path

# Keep generated bytecode off removable/cloud-coordinated project folders.
sys.pycache_prefix = os.environ.get('PYTHONPYCACHEPREFIX', str(Path(tempfile.gettempdir()) / ('eventpilot_v12_pycache_' + str(os.getuid() if hasattr(os, 'getuid') else 'user'))))

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from eventpilot.io import digest, file_digest, read_json, read_jsonl, write_json, write_jsonl
from eventpilot.input_budget import INPUT_PROTOCOL, MAX_INPUT_BYTES
from eventpilot.json_protocol import extract_object
from eventpilot.providers import Model, ProviderError
from eventpilot.methods.paper import METHODS, PaperSession, MethodBudgetExhausted, options as method_options

EXPERIMENTS = ('main', 'ablation', 'counterfactual', 'multi', 'baseline')
CONTEXT_ABLATIONS = ('context_ablation_goal', 'context_ablation_state', 'context_ablation_multi')
AVAILABLE_EXPERIMENTS = EXPERIMENTS + CONTEXT_ABLATIONS
VIEWS = ('event-only', 'goal', 'state')
CONTEXT_VIEWS = ('event-only', 'goal', 'event-state', 'state')
DELIVERIES = ('sequential', 'batch', 'sequential_no_action')
RETRY_INFRA = {'provider_error', 'environment_error', 'source_unavailable', 'framework_error', 'registered_pending'}


def safe_key(value):
    if not value or not all(c.isalnum() or c in '_-.' for c in value):
        raise ValueError('Unsafe job/model identifier')
    return value


def baseline_cases(sources):
    """Fallback for release compilers: one independent native task per source."""
    return [{'schema_version': 'eventpilot.reviewed.11', 'case_id': 'BASE_' + tid,
             'experiment': 'baseline', 'cf_type': None, 'group_id': '', 'member': '',
             'layer': 'control', 'subtype': 'no_event', 'website': source['website'],
             'checkpoint': 0, 'tasks': {'A': {'source_task_id': tid, 'goal': source['goal']}},
             'initial_user_request': source['goal'], 'initial_registered_roles': ['A'],
             'events': [], 'private': {'source_lengths': {'A': len(source['steps'])}},
             'review': {'human_approved': True, 'method': 'matched_native_control', 'agreement': None}}
            for tid, source in sorted(sources.items())]


def load_data(data):
    cases = list(read_jsonl(data / 'cases.jsonl'))
    sources = read_json(data / 'sources.json')
    manifest = read_json(data / 'manifest.json')
    if not isinstance(manifest, dict) or not isinstance(sources, dict):
        raise ValueError('Missing dataset manifest or source catalog')
    if manifest.get('sources_sha256') and digest(sources) != manifest['sources_sha256']:
        raise ValueError('Frozen source catalog identity mismatch')
    if len({c['case_id'] for c in cases}) != len(cases):
        raise ValueError('Duplicate case IDs')
    for c in cases:
        for task in c['tasks'].values():
            tid = task['source_task_id']
            if tid not in sources or task['goal'] != sources[tid]['goal']:
                raise ValueError('Registered task/source goal mismatch')
        if c['review'].get('human_approved') is not True:
            raise ValueError('This runner requires approved reviewed cases')
    baseline_path = data / 'baselines.jsonl'
    controls = list(read_jsonl(baseline_path)) if baseline_path.exists() else baseline_cases(sources)
    return cases, controls, sources, manifest


def filter_cases(cases, case_ids=None, limit=None):
    selected = list(cases)
    if case_ids:
        requested = set(case_ids.split(','))
        found = {c['case_id'] for c in selected} & requested
        if found != requested:
            raise ValueError('Unknown case ID: ' + ','.join(sorted(requested - found)))
        selected = [c for c in selected if c['case_id'] in requested]
        groups = {(c['cf_type'], c['group_id']) for c in selected if c.get('cf_type')}
        selected_ids = {c['case_id'] for c in selected}
        selected = [c for c in cases if c['case_id'] in selected_ids or
                    c.get('cf_type') and (c['cf_type'], c['group_id']) in groups]
    if limit is not None:
        # Limits apply independently to Main cases, complete CF groups, and
        # Multi cases. No pair/triple is partially registered.
        choices = set()
        for exp in ('main', 'multi'):
            choices.update(c['case_id'] for c in [x for x in selected if x['experiment'] == exp][:limit])
        for kind in ('goal', 'state', 'semantic'):
            groups = list(dict.fromkeys(c['group_id'] for c in selected if c.get('cf_type') == kind))[:limit]
            choices.update(c['case_id'] for c in selected if c.get('cf_type') == kind and c['group_id'] in groups)
        selected = [c for c in selected if c['case_id'] in choices]
    return selected


def jobs_for(cases, controls, models, experiments, repeats, deliveries):
    jobs, aliases = [], []
    by_exp = {'main': [c for c in cases if c['experiment'] == 'main'],
              'ablation': [c for c in cases if c['experiment'] == 'main'],
              'counterfactual': [c for c in cases if c['experiment'] == 'counterfactual'],
              'multi': [c for c in cases if c['experiment'] == 'multi'], 'baseline': controls,
              'context_ablation_goal': [c for c in cases if c.get('cf_type') == 'goal'],
              'context_ablation_state': [c for c in cases if c.get('cf_type') == 'state'],
              'context_ablation_multi': [c for c in cases if c['experiment'] == 'multi']}
    for model in models:
        safe_key(model)
        for exp in experiments:
            views = CONTEXT_VIEWS if exp in CONTEXT_ABLATIONS else VIEWS if exp == 'ablation' else ('state',) if exp=='main' else ('trajectory',)
            for view in views:
                for repeat in range(repeats):
                    for case in by_exp[exp]:
                        for delivery in deliveries if exp in ('multi', 'context_ablation_multi') else ('sequential',):
                            identity = (model, exp, view, str(repeat), case['case_id'], delivery)
                            key = safe_key('__'.join(identity))
                            job = dict(zip(('model', 'experiment', 'view', 'repeat', 'case_id', 'delivery'),
                                           (model, exp, view, repeat, case['case_id'], delivery)), key=key)
                            if exp == 'ablation' and view == 'state' and 'main' in experiments:
                                target = key.replace('__ablation__', '__main__', 1)
                                aliases.append({**job, 'alias_job_key': key, 'canonical_job_key': target})
                            else:
                                jobs.append(job)
    return jobs, aliases


def code_identity():
    files = sorted(x for x in (ROOT / 'eventpilot').rglob('*.py') if x.stem.isidentifier()) + [Path(__file__).resolve()]
    return digest({x.relative_to(ROOT).as_posix(): file_digest(x) for x in files})


def runtime_identity():
    versions={}
    for name in ('httpx','lxml','openpyxl'):
        try:versions[name]=version(name)
        except PackageNotFoundError:versions[name]=None
    return {'python':'.'.join(map(str,sys.version_info[:3])),'packages':versions}


@contextmanager
def run_lock(root):
    """OS advisory ownership; process exit releases it even after a crash."""
    root.mkdir(parents=True, exist_ok=True)
    stream = (root / '.runner.lock').open('a+b')
    try:
        if os.name == 'nt':
            import msvcrt
            if stream.seek(0, 2) == 0:
                stream.write(b'0'); stream.flush()
            stream.seek(0)
            try:
                msvcrt.locking(stream.fileno(), msvcrt.LK_NBLCK, 1)
            except OSError:
                raise RuntimeError('Another runner owns this run-root') from None
        else:
            import fcntl
            try:
                fcntl.flock(stream, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                raise RuntimeError('Another runner owns this run-root') from None
        yield
    finally:
        stream.close()


def report(root):
    from eventpilot.report import export
    print('[EXPORT] Building tables from registered denominators and closed records; no model API calls.', flush=True)
    try:
        return export(root)
    except Exception as error:
        # Export failures must not destroy closed model records or require
        # spending tokens again. The traceback remains available to repair.
        import traceback
        target = root / 'report_error.txt'
        target.write_text(traceback.format_exc(), encoding='utf-8')
        raise RuntimeError('Records retained; report failed. Inspect ' + str(target)) from error


async def execute(args, corpus, cases, controls, jobs, root, config):
    from eventpilot.engine import Session
    queue, sem, stop = asyncio.Queue(), asyncio.Semaphore(args.api_concurrency), asyncio.Event()
    cache_locks, blocked = {}, {}
    counts = {'completed': 0, 'cached': 0, 'active': 0, 'api_calls': 0,
              'prefix_cache_hits': 0, 'registered': len(jobs)}
    activity = {'message': 'starting', 'time': time.monotonic()}
    index = {c['case_id']: c for c in cases + controls}
    for job in jobs:
        previous = read_json(root / 'records' / (job['key'] + '.json'))
        if previous and args.resume and not (args.retry_infra and previous['status'] in RETRY_INFRA):
            counts['completed'] += 1; counts['cached'] += 1
        else:
            queue.put_nowait(job)

    def progress():
        write_json(root / 'progress.json', {**counts, 'queued': queue.qsize(), 'stopped': stop.is_set(),
                                           'last_activity': activity['message'], 'updated_unix': time.time()})

    async def ticker():
        while True:
            await asyncio.sleep(15)
            print(f'[LIVE] completed {counts["completed"]}/{len(jobs)} canonical '
                  f'(cached={counts["cached"]}, active={counts["active"]}, calls={counts["api_calls"]}, '
                  f'prefix_cache={counts["prefix_cache_hits"]}); {activity["message"]}; '
                  f'{time.monotonic() - activity["time"]:.0f}s ago', flush=True)
            progress()

    async def worker(worker_id):
        while not stop.is_set():
            try:
                job = queue.get_nowait()
            except asyncio.QueueEmpty:
                return
            counts['active'] += 1
            key, name = job['key'], job['model']
            folder = root / 'attempts' / key / f'attempt_{time.time_ns()}'
            folder.mkdir(parents=True, exist_ok=True)
            env, interrupted = None, False
            # A model adapter is bound to this episode, so usage cannot leak
            # across concurrent jobs or prefix-cache waiters.
            model = Model(name, config)
            try:
                env = Session(index[job['case_id']], corpus, name, job['experiment'], job['view'], job['repeat'],
                              delivery=job['delivery'], max_commands=args.max_commands,
                              candidate_limit=args.candidate_limit)
                method = getattr(args, 'method', 'direct')
                if method != 'direct':
                    env = PaperSession(env, method,
                                       max_requests=getattr(args,'max_model_requests',1024),
                                       reflexion_trials=getattr(args,'reflexion_trials',2))
                else:
                    env.episode['method'] = 'direct'
                env.episode['job_key'] = key
                env.episode.setdefault('calls', [])
                while True:
                    if name in blocked:
                        raise blocked[name]
                    request = env.next_request()
                    if request is None:
                        break
                    if len(env.episode['calls']) >= getattr(args, 'max_model_requests', 1024):
                        raise MethodBudgetExhausted('max_model_requests_per_episode')
                    role, messages = request['role'], request['messages']
                    record = {'role': role, 'messages': copy.deepcopy(messages), 'started_unix': time.time(),
                              'method_stage':request.get('method_stage','direct'),
                              'method_trial':request.get('method_trial',1),
                              'input_protocol': INPUT_PROTOCOL,
                              'input_bytes': sum(len(m['content'].encode('utf-8')) for m in messages)}
                    env.episode['calls'].append(record)
                    activity.update(message=f'{key} {role} {record["method_stage"]} calling', time=time.monotonic())
                    cache_key = digest({'messages': messages, 'model': name, 'repeat': job['repeat'],
                                        'method':method,'stage':request.get('method_stage','direct'),
                                        'output_tokens': args.output_tokens}) if role == 'prefix' else None
                    cache_path = root / 'prefix_cache' / (cache_key + '.json') if cache_key else None

                    async def actual_call():
                        async with sem:
                            if name in blocked:
                                raise blocked[name]
                            counts['api_calls'] += 1
                            record['api_called'] = True
                            record['transport_started_unix'] = time.time()
                            raw = await asyncio.to_thread(model.call, messages, args.output_tokens)
                        try:
                            parsed = extract_object(str(raw))
                            json.dumps(parsed,allow_nan=False)
                        except (ValueError,TypeError,RecursionError):
                            parsed = None
                        return {'raw_output': str(raw), 'parsed': parsed,
                                'response_diagnostics': getattr(raw, 'diagnostics', {}),
                                'usage': copy.deepcopy(model.usage[-1]) if model.usage else None}

                    try:
                        if cache_key:
                            async with cache_locks.setdefault(cache_key, asyncio.Lock()):
                                result = read_json(cache_path)
                                if result is not None:
                                    if result['prompt_digest'] != digest(messages) or result['model'] != name or result['repeat'] != job['repeat']:
                                        raise RuntimeError('Prefix cache identity mismatch')
                                    counts['prefix_cache_hits'] += 1
                                    record['response_origin'] = 'identical_prompt_cached_model_prediction'
                                else:
                                    result = await actual_call()
                                    result.update(prompt_digest=digest(messages), model=name, repeat=job['repeat'])
                                    write_json(cache_path, result)
                                    record['response_origin'] = 'new_model_prediction'
                        else:
                            result = await actual_call()
                            record['response_origin'] = 'new_model_prediction'
                        record.update({k: copy.deepcopy(result.get(k)) for k in ('raw_output', 'parsed', 'response_diagnostics')})
                        record.update(api_ok=True,
                                      api_called=record['response_origin'] == 'new_model_prediction',
                                      finished_unix=time.time())
                        record['usage'] = copy.deepcopy((result.get('usage') or {}).get('usage')) if record['api_called'] else None
                    except ProviderError as error:
                        record.update(api_ok=False, error_diagnostics=error.diagnostics, finished_unix=time.time())
                        raise
                    env.accept(result['parsed'], role)
                    activity.update(message=f'{key} {role} {record["method_stage"]} returned', time=time.monotonic())
                    write_json(folder / 'in_progress.json', env.snapshot())
                episode = env.close()
            except MethodBudgetExhausted as error:
                episode=env.close('method_budget_exhausted',{'category':str(error)})
            except ProviderError as error:
                if error.diagnostics['quota_exhausted'] or error.diagnostics['category'] in {'authentication_error', 'model_or_endpoint_unavailable'}:
                    blocked[name] = error
                    stop.set()
                episode = env.close('provider_error', error.diagnostics) if env else {**job, 'status': 'provider_error', 'error_diagnostics': error.diagnostics}
            except OSError as error:
                diagnostics = {'category': type(error).__name__, 'errno': error.errno}
                episode = env.close('source_unavailable', diagnostics) if env else {**job, 'status': 'source_unavailable', 'error_diagnostics': diagnostics}
            except asyncio.CancelledError:
                interrupted = True
                if env:
                    write_json(folder / 'in_progress.json', env.snapshot())
                raise
            except Exception as error:
                import traceback
                (folder / 'error_traceback.txt').write_text(traceback.format_exc(), encoding='utf-8')
                diagnostics = {'category': type(error).__name__, 'message': str(error)[:250]}
                episode = env.close('framework_error', diagnostics) if env else {**job, 'status': 'framework_error', 'error_diagnostics': diagnostics}
                stop.set()
            finally:
                counts['active'] -= 1
            if interrupted:
                return
            episode.update({k: job[k] for k in ('model', 'experiment', 'view', 'repeat', 'case_id', 'delivery')})
            episode.update(job_key=key, usage=copy.deepcopy(model.usage), attempt_finished_unix=time.time())
            episode['method']=getattr(args,'method','direct')
            episode['efficiency']={'model_requests':len(episode.get('calls',[])),
                                   'api_calls':sum(c.get('api_called') is True for c in episode.get('calls',[])),
                                   'cache_hits':sum(c.get('response_origin')=='identical_prompt_cached_model_prediction' for c in episode.get('calls',[])),
                                   'model_call_seconds':sum(max(0,c.get('finished_unix',c['started_unix'])-c['started_unix']) for c in episode.get('calls',[])),
                                   'scope':'retained attempt; summed call duration includes cache wait and is not wall-clock throughput'}
            path = root / 'records' / (key + '.json')
            previous = read_json(path)
            if previous:
                write_json(folder / 'previous_record.json', previous)
            write_json(folder / 'record.json', episode)
            write_json(path, episode)
            counts['completed'] += 1
            queue.task_done()
            print(f'[{counts["completed"]}/{len(jobs)}] {key}: {episode["status"]} '
                  f'JointReplayESR={episode.get("evaluation", {}).get("episode_success")}', flush=True)
            progress()
    heartbeat = asyncio.create_task(ticker())
    workers = [asyncio.create_task(worker(i)) for i in range(args.workers)]
    try:
        await asyncio.gather(*workers)
    finally:
        for task in workers:
            if not task.done():
                task.cancel()
        await asyncio.gather(*workers, return_exceptions=True)
        heartbeat.cancel()
        await asyncio.gather(heartbeat, return_exceptions=True)
        progress()
    if stop.is_set():
        print('[PAUSED] Quota/auth/provider or framework error; unstarted jobs remain pending. '
              'Use --resume --retry-infra after resolving it.', flush=True)
    return stop.is_set()


def main(argv=None):
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--data', type=Path, default=ROOT / 'data')
    p.add_argument('--config', type=Path, default=ROOT / 'models.json')
    p.add_argument('--corpus-root', type=Path)
    p.add_argument('--only', default='gateway_ds')
    p.add_argument('--experiments', default='main')
    p.add_argument('--deliveries', default=','.join(DELIVERIES))
    p.add_argument('--case-ids')
    p.add_argument('--case-limit', type=int)
    p.add_argument('--run-root', type=Path, required=True)
    p.add_argument('--workers', type=int, default=8)
    p.add_argument('--api-concurrency', type=int, default=4)
    p.add_argument('--repeats', type=int, default=1)
    p.add_argument('--max-commands', type=int, default=128)
    p.add_argument('--candidate-limit', type=int, default=50)
    p.add_argument('--output-tokens', type=int, default=8192)
    p.add_argument('--method', choices=METHODS, default='direct')
    p.add_argument('--reflexion-trials', type=int, choices=(1,2,3), default=2,
                   help='Fixed local selection trials, public self-evaluation only; no Gold feedback')
    p.add_argument('--max-model-requests', type=int, default=1024,
                   help='Per-episode cap including auxiliary and cached logical requests')
    p.add_argument('--job-order-seed', type=int, default=20261105)
    p.add_argument('--resume', action='store_true')
    p.add_argument('--retry-infra', action='store_true')
    p.add_argument('--dry-run', action='store_true')
    p.add_argument('--export-only', action='store_true')
    a = p.parse_args(argv)
    root = a.run_root.expanduser().resolve()
    if a.export_only:
        print(json.dumps(report(root), ensure_ascii=False, indent=2)); return
    for key in ('workers', 'api_concurrency', 'repeats', 'max_commands', 'candidate_limit', 'output_tokens','max_model_requests'):
        if getattr(a, key) < 1:
            p.error(key + ' must be positive')
    if a.case_limit is not None and a.case_limit < 1:
        p.error('case-limit must be positive')
    names, experiments, deliveries = a.only.split(','), a.experiments.split(','), a.deliveries.split(',')
    for values, allowed, label in [(names, None, 'models'), (experiments, AVAILABLE_EXPERIMENTS, 'experiments'), (deliveries, DELIVERIES, 'deliveries')]:
        if not values or len(set(values)) != len(values) or allowed and not set(values) <= set(allowed):
            p.error('Unknown/duplicate ' + label)
    from eventpilot.compiler import validate
    validate(a.data)
    cases, controls, sources, data_manifest = load_data(a.data)
    cases = filter_cases(cases, a.case_ids, a.case_limit)
    selected_task_ids = {t['source_task_id'] for c in cases for t in c['tasks'].values()}
    controls = [c for c in controls if c['tasks']['A']['source_task_id'] in selected_task_ids]
    jobs, aliases = jobs_for(cases, controls, names, experiments, a.repeats, deliveries)
    if not jobs:
        p.error('No selected jobs')
    # Register only cases actually in this run. In particular the independent
    # context ablation must not appear to contain Main/Semantic or unrun
    # baseline controls just because they exist in the full release.
    registered_ids = {j['case_id'] for j in jobs + aliases}
    cases = [c for c in cases if c['case_id'] in registered_ids]
    controls = [c for c in controls if c['case_id'] in registered_ids]
    task_ids = {t['source_task_id'] for c in cases + controls for t in c['tasks'].values()}
    config = read_json(a.config)
    models = [m for m in config['models'] if m['name'] in names]
    if len(models) != len(names):
        p.error('Unknown configured model name')
    for model in models:
        safe_key(model['name'])
        if model.get('backend') != 'chat-completions':
            p.error('Unsupported model backend')
        if 'api_key' in model or 'key' in model:
            p.error('Credentials must be environment variables, not config values')
    # Corpus loading and frozen hashes are local-only. They never access websites.
    from eventpilot.corpus import Corpus
    corpus_path = a.corpus_root or os.environ.get('EP_CORPUS_ROOT') or ROOT / 'corpus'
    corpus = Corpus(corpus_path)
    corpus.expected_snapshot_hashes = {(tid, i): sha for tid, s in sources.items()
                                      for i, sha in enumerate(s.get('audit', {}).get('snapshot_hashes', []))}
    for tid in task_ids:
        if tid not in corpus.tasks:
            p.error('Missing registered source task: ' + tid)
    index_digest = file_digest(Path(corpus.root) / 'data/normalized/tasks.jsonl')
    registered_index = data_manifest.get('source', {}).get('index_sha256')
    if registered_index and registered_index != index_digest:
        p.error('Frozen Mind2Web task index changed')
    random.Random(a.job_order_seed).shuffle(jobs)
    manifest = {'protocol': 'eventpilot.paper_methods.12', 'models': names, 'experiments': experiments,
                'deliveries': deliveries, 'repeats': a.repeats,
                'dataset_digest': data_manifest.get('dataset_digest', digest(cases)),
                'registered_cases_digest': digest(cases + controls),
                'source_index_sha256': index_digest, 'model_config': models,
                'provider_defaults': {k: v for k, v in config.items() if k not in ('models', 'note')},
                'code_sha256': code_identity(), 'runtime':runtime_identity(), 'job_order_seed': a.job_order_seed,
                'input_protocol': INPUT_PROTOCOL, 'max_input_bytes': MAX_INPUT_BYTES,
                'method': a.method,
                'method_options': method_options(a.method,a.max_model_requests,a.reflexion_trials),
                'information_protocol':{'main':'state','ablation':list(VIEWS),
                                        'context_ablation':list(CONTEXT_VIEWS),
                                        'counterfactual_multi_baseline':'trajectory',
                                        'actor_protocol':'unchanged public tools and observed history'},
                'budgets': {k: getattr(a, k) for k in ('max_commands', 'candidate_limit', 'output_tokens')},
                'canonical_jobs': len(jobs), 'logical_jobs': len(jobs) + len(aliases),
                'human_reviewed': all(c['review'].get('human_approved') is True for c in cases),
                'review_method': 'single_user_workbook_approval', 'inter_annotator_agreement': None,
                'real_website_outcome_evaluated': False,
                'execution_scope': 'staged_event_conditioned_teacher_forced_actions_and_control'}
    print(json.dumps({**manifest, 'workers': a.workers, 'api_concurrency': a.api_concurrency,
                      'unique_reviewed_cases': len(cases), 'native_controls': len(controls)}, ensure_ascii=False, indent=2), flush=True)
    if a.dry_run:
        return
    for m in models:
        if not os.environ.get(m['api_key_env']):
            p.error('Set ' + m['api_key_env'] + ' in the terminal before starting')
    with run_lock(root):
        previous = read_json(root / 'run_manifest.json')
        if previous:
            if not a.resume:
                p.error('Existing run: use --resume or select a new run-root')
            if previous != manifest:
                p.error('Resume identity mismatch: code/data/model/budgets must remain unchanged; workers may change')
        else:
            if any((root / 'records').glob('*.json')):
                p.error('Orphan records exist without run_manifest.json; choose a clean run-root')
            write_json(root / 'run_manifest.json', manifest)
            write_json(root / 'jobs.json', jobs)
            write_json(root / 'aliases.json', aliases)
            write_jsonl(root / 'registered_data/cases.jsonl', cases)
            write_jsonl(root / 'registered_data/baseline.jsonl', controls)
            write_json(root / 'registered_sources.json', sources)
            write_json(root / 'pair_registry.json', read_json(a.data / 'pair_registry.json', []))
        stopped = False
        try:
            stopped = asyncio.run(execute(a, corpus, cases, controls, jobs, root, a.config))
        except KeyboardInterrupt:
            print('\n[INTERRUPTED] Closed records retained. Unclosed episodes remain pending for resume.', flush=True)
            stopped = True
        finally:
            print(json.dumps(report(root), ensure_ascii=False, indent=2), flush=True)
        if stopped:
            raise SystemExit(2)


if __name__ == '__main__':
    main()
